<script setup>
import {computed,ref} from 'vue'
import {useAuthStore} from '../stores/auth'
import {useMarketStore} from '../stores/market'
import {LOCATIONS} from '../data/seed'
import {action,date,money,ui} from '../lib/ui'
import Icon from '../components/Icon.vue'
const auth=useAuthStore(),market=useMarketStore(),filter=ref('all'),role=ref('buy'),modal=ref(null),busy=ref(false)
const labels={unpaid:'待模拟付款',paid:'待面交',completed:'已完成',cancelled:'已取消'}
const orders=computed(()=>market.userOrders(auth.user.id).filter(o=>(role.value==='buy'?o.buyerId===auth.user.id:o.sellerId===auth.user.id)&&(filter.value==='all'||o.status===filter.value)))
function open(order,kind){modal.value={order,kind}}
async function confirm(){busy.value=true;const {order,kind}=modal.value;const fn=kind==='pay'?'payOrder':kind==='complete'?'completeOrder':'cancelOrder';const result=await action(()=>market[fn](auth.user.id,order.id),kind==='pay'?'模拟付款完成，请联系卖家约定面交':kind==='complete'?'面交完成，好物有了新归宿':'订单已取消，物品已释放');busy.value=false;if(result)modal.value=null}
function map(id){ui.mapLocation=id;ui.mapOpen=true}
</script>
<template><div class="page-width inner-page"><div class="page-title"><span class="eyebrow">EVERY EXCHANGE, A NEW STORY</span><h1>每一次交接，都是新的开始。</h1><p>从一份心动，到一次校园相遇。</p></div><div class="order-navigation"><div class="segmented"><button :class="{active:role==='buy'}" @click="role='buy'">我买到的</button><button :class="{active:role==='sell'}" @click="role='sell'">我卖出的</button></div><div class="order-filter"><button v-for="item in [{id:'all',label:'全部订单'},...Object.entries(labels).map(([id,label])=>({id,label}))]" :key="item.id" :class="{active:filter===item.id}" @click="filter=item.id">{{item.label}}</button></div></div><div v-if="!orders.length" class="panel empty-state"><Icon name="order" :size="46"/><h2>这页故事，等待开始</h2><p>{{role==='buy'?'还没有这一状态的订单，去挑一件喜欢的闲置吧。':'还没有这一状态的卖出订单，好物正在等待新的主人。'}}</p><RouterLink :to="role==='buy'?'/market':'/profile'" class="button primary">{{role==='buy'?'去逛市集':'查看我的闲置'}}<Icon name="arrow" :size="17"/></RouterLink></div><article v-for="order in orders" :key="order.id" class="panel order-card"><div class="order-card-header"><span><Icon name="user" :size="17"/>{{role==='buy'?order.sellerName:order.buyerName}}<small>{{role==='buy'?'的闲置':'的心动清单'}}</small></span><small>{{date(order.createdAt)}} · {{order.id.slice(-8).toUpperCase()}}</small><span :class="['order-status',order.status]">{{labels[order.status]}}</span></div><div v-for="item in order.items" :key="item.id" class="order-item"><RouterLink :to="`/product/${item.id}`"><img :src="item.images?.[0]" :alt="item.title"/></RouterLink><div><RouterLink :to="`/product/${item.id}`">{{item.title}}</RouterLink><small>校园面交 · 1 件</small></div><strong>¥{{money(item.price)}}</strong></div><div class="order-location"><button class="text-link" @click="map(order.locationId)"><Icon name="pin" :size="16"/>{{LOCATIONS.find(p=>p.id===order.locationId)?.name}}<Icon name="chevron" :size="14"/></button><span v-if="order.note">留言：{{order.note}}</span><strong>合计 <span class="rose">¥{{money(order.amount)}}</span></strong></div><div class="order-card-footer"><RouterLink :to="{path:'/messages',query:{partner:role==='buy'?order.sellerId:order.buyerId,product:order.productIds[0]}}" class="text-link"><Icon name="message" :size="17"/>联系{{role==='buy'?'卖家':'买家'}}</RouterLink><span v-if="order.status==='paid'" class="muted">{{role==='buy'?'当面验货后，记得确认完成面交。':'等待买家面交后确认完成。'}}</span><button v-if="['unpaid','paid'].includes(order.status)" class="button subtle" @click="open(order,'cancel')">取消订单</button><button v-if="order.status==='unpaid'&&role==='buy'" class="button primary" @click="open(order,'pay')">模拟付款<Icon name="arrow" :size="16"/></button><button v-if="order.status==='paid'&&role==='buy'" class="button primary" @click="open(order,'complete')"><Icon name="check" :size="17"/>确认已完成面交</button><span v-if="order.status==='completed'" class="completed-note"><Icon name="leaf" :size="17"/>好物已经有了新归宿</span></div></article><Teleport to="body"><div v-if="modal" class="modal-overlay" @click.self="!busy&&(modal=null)"><section class="modal confirmation-modal" role="dialog" aria-modal="true" aria-label="确认订单操作"><span class="confirmation-icon"><Icon :name="modal.kind==='pay'?'shield':modal.kind==='complete'?'leaf':'info'" :size="32"/></span><h2>{{modal.kind==='pay'?'模拟支付，安心演示。':modal.kind==='complete'?'好物已经到你手中了吗？':'确定取消这次相遇吗？'}}</h2><p>{{modal.kind==='pay'?'这是课堂演示支付，不会产生任何真实扣款。':modal.kind==='complete'?'请确认已在校内完成交接，并当面检查了物品。':'取消后物品将重新开放购买；若已模拟付款，也不会产生真实退款。'}}</p><strong v-if="modal.kind==='pay'" class="payment-amount">¥{{money(modal.order.amount)}}</strong><div class="modal-buttons"><button class="button outline" :disabled="busy" @click="modal=null">再想一想</button><button class="button primary" :disabled="busy" @click="confirm">{{busy?'处理中…':modal.kind==='pay'?'确认模拟付款':modal.kind==='complete'?'已验货，确认完成':'确认取消订单'}}</button></div></section></div></Teleport></div></template>
